begin;
select plan(18);
select has_function('public','consume_request_limit',array['text','text'],'shared limiter RPC exists');
select is(has_function_privilege('anon','public.consume_request_limit(text,text)','execute'),false,'anonymous cannot invoke limiter');
select is(has_function_privilege('authenticated','public.consume_request_limit(text,text)','execute'),false,'members cannot bypass application limits');
select is(has_function_privilege('service_role','public.consume_request_limit(text,text)','execute'),true,'server can invoke limiter');
select is((select count(*)::integer from cron.job where jobname='purge-request-limits' and active),1,'idle cleanup is scheduled');
select is((select schedule from cron.job where jobname='purge-request-limits'),'*/15 * * * *','cleanup runs every fifteen minutes');
select lives_ok($$select public.consume_request_limit('signin',repeat('a',64))$$,'valid server request');
select public.consume_request_limit('signin',repeat('a',64)) from generate_series(1,9);
select is((select allowed from public.consume_request_limit('signin',repeat('a',64))),false,'eleventh attempt denied across invocations');
select ok((select retry_after_seconds between 1 and 900 from public.consume_request_limit('signin',repeat('a',64))),'denial includes bounded retry');
select public.consume_request_limit('write',repeat('b',64)) from generate_series(1,60);
select is((select allowed from public.consume_request_limit('write',repeat('b',64))),false,'sixty first write denied');
select throws_ok($$select public.consume_request_limit('unconfigured',repeat('c',64))$$,'22023','invalid limit request','unknown scope denied');
select throws_ok($$select public.consume_request_limit('signin','raw-ip')$$,'22023','invalid limit request','only digests accepted');
select is(has_table_privilege('anon','private.request_limits','select'),false,'anonymous cannot see hashes');
select is(has_table_privilege('authenticated','private.request_limits','select'),false,'members cannot see hashes');
insert into private.request_limits values ('write',repeat('e',64),1,now()-interval '1 day'),('write',repeat('f',64),1,now()+interval '1 minute');
do $$declare cleanup text; begin select command into cleanup from cron.job where jobname='purge-request-limits'; execute cleanup; end$$;
select is((select count(*)::integer from private.request_limits where subject_hash=repeat('e',64)),0,'scheduled command deletes idle expired rows without request activity');
select is((select count(*)::integer from private.request_limits where subject_hash=repeat('f',64)),1,'cleanup preserves active buckets');
update private.request_limits set expires_at=now()-interval '1 second' where scope='write' and subject_hash=repeat('b',64);
select is((select allowed from public.consume_request_limit('write',repeat('b',64))),true,'expired window resets');
select is((select attempts from private.request_limits where scope='write' and subject_hash=repeat('b',64)),1,'new window starts at one');
select * from finish();
rollback;
